import * as ev from 'node:events';
import EventEmitter from 'node:events';
function t(f: () => any): string { try { f(); return 'ok'; } catch (e: any) { return 'THROW ' + e.name + ' ' + e.code + ': ' + e.message; } }
function main(): void {
  const e: any = new EventEmitter();
  const m: any = ev;
  console.log(t(() => m.addAbortListener(null, () => {})));
  console.log(t(() => m.addAbortListener(new AbortController().signal, null)));
  console.log(t(() => m.getMaxListeners(null)));
  console.log(t(() => m.getMaxListeners({})));
  console.log(t(() => m.setMaxListeners('a')));
  console.log(t(() => m.setMaxListeners(-1)));
  console.log(t(() => m.setMaxListeners(1, {})));
  console.log(t(() => m.getEventListeners({}, 'x')));
  console.log(t(() => m.on({}, 'x')));
  console.log(t(() => m.on(e, 'x', 5)));
  console.log(t(() => e.on('x', null)));
  console.log(t(() => e.once('x', 's')));
  console.log(t(() => e.prependListener('x')));
  console.log(t(() => e.prependOnceListener('x', 1)));
  console.log(t(() => e.off('x')));
  console.log(t(() => e.removeListener('x', {})));
  console.log(t(() => e.setMaxListeners('a')));
  console.log(t(() => e.setMaxListeners(-1)));
  console.log(t(() => new EventEmitter({ captureRejections: 'a' })));
}
